// Welche Bestellquelle gemeint ist -- und was passiert, wenn keine eindeutig ist.
//
// `source_label` kommt aus der Tool-Konfiguration des Agenten, nicht vom
// Modell. Ist es leer und es gibt genau eine aktive Quelle, ist die gemeint.
// Gibt es mehrere und keine ist benannt, wird *nicht* geraten: die falsche
// Tabelle vorzulesen ist schlimmer, als zu sagen, dass es gerade nicht geht.
const asked = $('Order Requested').first().json;
const wanted = String(asked.source_label ?? '').trim().toLowerCase();
const sources = $input.all().map((item) => item.json ?? {}).filter((row) => row.id);

let source = null;
let problem = null;
if (sources.length === 0) {
  problem = 'keine Bestellquelle hinterlegt';
} else if (wanted) {
  source = sources.find((row) => String(row.label ?? '').trim().toLowerCase() === wanted) ?? null;
  if (!source) problem = 'die eingestellte Quelle gibt es nicht mehr';
} else if (sources.length === 1) {
  source = sources[0];
} else {
  problem = 'mehrere Quellen, im Agenten ist keine ausgewaehlt';
}

return [{
  json: {
    kind: source ? source.kind : 'none',
    label: source ? source.label : null,
    sheet_id: source ? source.sheet_id : null,
    sheet_range: source ? source.sheet_range : null,
    endpoint_url: source ? source.endpoint_url : null,
    match_column: source ? source.match_column : null,
    return_columns: source ? (source.return_columns ?? []) : [],
    problem,
  },
}];

// Die Stelle, an der entschieden wird, was der Anrufer hoeren darf.
//
// Aus der Quelle kommt die ganze Zeile: Einkaufspreis, Marge, interne Notiz,
// oft auch die Adresse eines anderen Kunden in der Nachbarspalte. Weiter
// gereicht wird ausschliesslich, was in `return_columns` steht. Die Auswahl
// passiert hier und nicht im System-Prompt -- ein Prompt ist eine Bitte, eine
// Projektion ist eine Tatsache.
const source = $('Pick Source').first().json;
const asked = $('Order Requested').first().json;
const ref = String(asked.order_ref ?? '').trim().toLowerCase();
const items = $input.all().map((item) => item.json ?? {});

let rows = [];
if (source.kind === 'google_sheet') {
  // Die Sheets-API liefert ein Raster, keine Objekte. Die erste Zeile sind die
  // Ueberschriften -- ohne sie waere `match_column` nicht auffindbar.
  const grid = Array.isArray(items[0]?.values) ? items[0].values : [];
  const [header = [], ...body] = grid;
  rows = body.map((row) => Object.fromEntries(
    header.map((name, index) => [String(name).trim(), row[index] ?? '']),
  ));
} else if (source.kind === 'http') {
  // Fremde Endpunkte antworten in jeder erdenklichen Form. Ein Array kommt bei
  // n8n als mehrere Items an, ein Objekt mit Liste darin als eines.
  const first = items[0] ?? {};
  const nested = [first.orders, first.data, first.items, first.results].find((value) => Array.isArray(value));
  rows = nested ?? items.filter((row) => row && Object.keys(row).length > 0);
}

const hit = rows.find((row) => String(row?.[source.match_column] ?? '').trim().toLowerCase() === ref) ?? null;
const allowed = Array.isArray(source.return_columns) ? source.return_columns : [];
const order = hit ? Object.fromEntries(allowed.filter((column) => column in hit).map((column) => [column, hit[column]])) : null;
const released = order ? Object.keys(order).length : 0;

// Vier Ausgaenge, vier Saetze. Der dritte ist der unangenehme: die Bestellung
// gibt es, aber keine freigegebene Spalte steht in der Zeile -- ein Tippfehler
// in der Konfiguration, kein Fehler des Anrufers. Er wird als `error`
// protokolliert und taucht damit im Betriebs-Screen auf, statt jedem Anrufer
// als "nicht gefunden" verkauft zu werden.
let status = 'success';
let result;
if (source.problem) {
  status = 'error';
  result = 'Es laesst sich gerade keine Bestellung nachschlagen. Sage das offen, nenne keinen Grund aus der Technik, und biete die Uebergabe an einen Menschen an.';
} else if (!hit) {
  result = 'Zu dieser Nummer gibt es keine Bestellung. Frag nach, ob die Nummer stimmt, und biete sonst die Uebergabe an einen Menschen an.';
} else if (released === 0) {
  status = 'error';
  result = 'Die Bestellung gibt es, aber es sind keine Angaben dazu freigegeben. Sage das offen und biete die Uebergabe an einen Menschen an.';
} else {
  result = 'Bestellung gefunden. Nenne ausschliesslich diese Angaben und erfinde nichts dazu: ' + JSON.stringify(order);
}

return [{
  json: {
    found: !!hit,
    order,
    source: source.label,
    rows_scanned: rows.length,
    diagnosis: source.problem ?? null,
    status,
    result,
  },
}];
